#------------------------------------------------------------------------------
# Reduce the number of taxa considered if they do not provide enough information, 
# i.e. many zero counts in terms of the depth of the core.
#------------------------------------------------------------------------------


if(null.ratio.check ){
    null.ratio <- c()
    for(i in 1:ncol(all.avail)){
        null.ratio[i] <- length(which(all.avail[,i] == 0)) /  nrow(all.avail) 
    }
    # keep all available relict taxa 
    if(sitename == "Lake Ohrid"){
        relict.id <- c(3,8,23,24,25)
        null.ratio[relict.id] <- 0
        # remove pinus sylvestris
        null.ratio[1] <- 1
    }

    # remove the rarest taxa and limit the core to 15 taxa 
    rm.id1 <- which(null.ratio >= 0.95)
    if(ncol(all.avail) - length(rm.id1) > 15) metro_hastings <- TRUE
    if(!metro_hastings){
        rm.id <- which(null.ratio %in% sort(null.ratio)[16:ncol(all.avail)])
        if( length(rm.id) == ncol(all.avail) ) next()
        if( length(rm.id) >= 1 ) all.avail <- all.avail[,-rm.id]
        sorting.available.spectrum <-  colMeans(all.avail, na.rm = T)
    }else{
        # remove the rarest taxa
        rm.id <- which(null.ratio >= 0.95)
        if( length(rm.id) == ncol(all.avail) ) next()
        if( length(rm.id) >= 1 ) all.avail <- all.avail[,-rm.id]
        sorting.available.spectrum <-  colMeans(all.avail, na.rm = T)
    }

}


